const labels={en:'English','zh-CN':'简体中文','zh-TW':'繁體中文',th:'ไทย',ru:'Русский'}
export function currentLocale(){const saved=localStorage.getItem('thaitype-locale');if(labels[saved])return saved;const l=(navigator.languages?.[0]||navigator.language||'en').toLowerCase();if(/^zh-(tw|hk|mo)/.test(l)||l.includes('hant'))return'zh-TW';if(l.startsWith('zh'))return'zh-CN';if(l.startsWith('th'))return'th';if(l.startsWith('ru'))return'ru';return'en'}
export const locale=currentLocale()

