const traditional=text=>[...text].map(c=>traditionalMap[c]||c).join('').replaceAll('控製','控制')
function exact(text){if(locale==='zh-CN')return text;if(locale==='zh-TW')return traditional(text);const english=en[text]||text;if(locale==='en')return english;return (locale==='th'?th[english]:ru[english])||english}
export const tr=exact

export function selector(className='language-switch'){return `<select class="${className}" data-language aria-label="Language">${Object.entries(labels).map(([k,v])=>`<option value="${k}"${k===locale?' selected':''}>${v}</option>`).join('')}</select>`}
export function localize(root=document){
  document.documentElement.lang=locale
  document.title=location.pathname.includes('assessment')?exact('候选人测评')+' · ThaiType Business':location.pathname.includes('portal')?exact('招聘测评控制台')+' · ThaiType Business':document.title
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode)
  for(const node of nodes){if(node.parentElement?.closest('.source[lang="th"],[data-no-translate],script,style'))continue;const raw=node.nodeValue,trim=raw.trim();if(!trim)continue;if(node.parentElement?.tagName==='OPTION'&&!node.parentElement.hasAttribute('value'))node.parentElement.value=trim;let translated=exact(trim)
    if(translated===trim&&locale!=='zh-CN')translated=parameterized(trim)
    if(translated!==trim)node.nodeValue=raw.replace(trim,translated)
  }
  root.querySelectorAll('[placeholder]').forEach(el=>el.placeholder=exact(el.placeholder.replace('…',''))+(el.placeholder.endsWith('…')?'…':''))
  root.querySelectorAll('[data-language]').forEach(el=>el.onchange=e=>{localStorage.setItem('thaitype-locale',e.target.value);location.reload()})
}
function parameterized(text){
  let mixed=text.match(/^目标 (\d+)$/);if(mixed)return `${exact('目标')} ${mixed[1]}`
  mixed=text.match(/^(\d+) 人 · (\d+) 字符\/分钟 · ([\d.]+)%$/);if(mixed)return `${mixed[1]} ${locale==='th'?'คน':locale==='ru'?'чел.':'people'} · ${mixed[2]} ${locale==='th'?'อักขระ/นาที':locale==='ru'?'символов/мин':'characters/min'} · ${mixed[3]}%`
  mixed=text.match(/^(\d+)\/(\d+) 项完成$/);if(mixed)return `${mixed[1]}/${mixed[2]} ${exact('项完成')}`
  if(text.includes('资料保留')&&text.includes('替代方案')){const days=text.match(/资料保留 (\d+) 天/)?.[1]||'';const features=['摄像头定时截图','人脸存在检测','麦克风异常检测'].filter(x=>text.includes(x)).map(exact).join(' · ');const retention=locale==='th'?`เก็บข้อมูล ${days} วัน`:locale==='ru'?`Хранение данных: ${days} дней`:`Data retained for ${days} days`;return `${features}${features?' · ':''}${retention}. ${exact('您可以联系招聘企业申请非摄像头替代方案。')}`}
  let match=text.match(/^(\d+) 次测评$/);if(match)return locale==='th'?`${match[1]} การประเมิน`:locale==='ru'?`${match[1]} оценок`:`${match[1]} assessments`
  match=text.match(/^速率限制：(\d+) 次\/小时$/);if(match)return locale==='th'?`จำกัดอัตรา: ${match[1]} ครั้ง/ชั่วโมง`:locale==='ru'?`Лимит: ${match[1]} запросов/час`:`Rate limit: ${match[1]} requests/hour`
  const rules=[[/^第 (\d+) \/ (\d+) 题 · (.+)$/,(_,a,b,type)=>`${locale==='th'?'ข้อ':locale==='ru'?'Задание':'Question'} ${a} / ${b} · ${exact(type)}`],[/^剩余测评额度：$/,locale==='th'?'เครดิตคงเหลือ:':locale==='ru'?'Осталось тестов:':'Assessment credits:'],[/^数据保留 (\d+) 天$/,locale==='th'?'เก็บข้อมูล $1 วัน':locale==='ru'?'Хранение данных: $1 дней':'Data retention: $1 days'],[/^(\d+) 字符\/分钟$/,locale==='th'?'$1 อักขระ/นาที':locale==='ru'?'$1 символов/мин':'$1 characters/min'],[/^国家 \/ 地区：(.+)$/,(_,value)=>`${exact('国家 / 地区：')} ${value}`],[/^套餐：(.+)$/,(_,value)=>`${exact('套餐：')} ${exact(value)}`],[/^数据保留：(\d+) 天$/,(_,value)=>`${exact('数据保留：')} ${value} ${exact('天')}`],[/^(\d+) 分钟$/,locale==='th'?'$1 นาที':locale==='ru'?'$1 мин.':'$1 minutes'],[/^(\d+) 道$/,locale==='th'?'$1 ข้อ':locale==='ru'?'$1 заданий':'$1 questions'],[/^(\d+) 次正式提交$/,locale==='th'?'ส่งอย่างเป็นทางการ $1 ครั้ง':locale==='ru'?'$1 официальная попытка':'$1 formal submission'],[/^我已阅读测试说明，同意记录按键时间、页面离开、粘贴和设备信息用于本次招聘测评。数据保留 (\d+) 天。$/,locale==='th'?'ฉันได้อ่านคำแนะนำและยินยอมให้บันทึกจังหวะการกดแป้น การออกจากหน้า การวางข้อความ และข้อมูลอุปกรณ์เพื่อการประเมินนี้ ข้อมูลจะถูกเก็บ $1 วัน':locale==='ru'?'Я прочитал(а) инструкцию и согласен(на) на запись времени нажатий, выхода со страницы, вставки и данных устройства. Данные хранятся $1 дней.':'I have read the instructions and consent to recording keystroke timing, page exits, paste attempts and device information. Data is retained for $1 days.'],[/^报告编号 (.+)$/,locale==='th'?'หมายเลขรายงาน $1':locale==='ru'?'Номер отчета $1':'Report ID $1'],[/^(.+) · (企业管理员|招聘经理|面试官|只读成员)$/,(_,name,role)=>`${name} · ${exact(role)}`],[/^(.+)，您好。(.+)$/,locale==='th'?'สวัสดี $1 การประเมินนี้วัดความเร็ว ความแม่นยำ ความสม่ำเสมอ และความน่าเชื่อถือที่เกี่ยวข้องกับงาน โดยไม่ใช้สัญชาติ อายุ หรือเพศในการให้คะแนน':locale==='ru'?'Здравствуйте, $1. Тест оценивает связанную с работой скорость, точность, стабильность и достоверность; гражданство, возраст и пол не учитываются.':'Hello, $1. This assessment measures job-related Thai typing speed, accuracy, stability and integrity. Nationality, age and gender are not scored.'],[/^(.+) · (.+)$/,(_,a,b)=>`${exact(a)} · ${exact(b)}`]]
  for(const [regex,replacement] of rules)if(regex.test(text))return text.replace(regex,replacement)
  return locale==='zh-TW'?traditional(text):text
}
